INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_442', 'mbe', '442', '262', 'MBE-1978-83-part6', '', '42', 'The owner of Newacre executed and delivered to a power company a right-of-way deed for the building and maintenance of an overhead power line across Newacre. The deed was properly recorded. Newacre then passed through several intermediate conveyances until it was conveyed to Sloan about ten years after the date of the right-of-way deed. All the intermediate deeds were properly recorded, but none of them mentioned the right-of-way. Sloan entered into a written contract to sell Newacre to Jones. By the terms of the contract, Sloan promised to furnish an abstract of title to Jones. Sloan contracted directly with Abstract Company to prepare and deliver an abstract to Jones, and Abstract Company did so. The abstract omitted the right-of-way deed. Jones delivered the abstract to his attorney and asked the attorney for an opinion as to title. The attorney signed and delivered to Jones a letter stating that, from the attorney''s examination of the abstract, it was his "opinion that Sloan had a free and unencumbered marketable title to Newacre." Sloan conveyed Newacre to Jones by a deed which included covenants of general warranty and against encumbrances. Jones paid the full purchase price. After Jones had been in possession of Newacre for more than a year, he learned about the right-of-way deed. Sloan, Jones, Abstract Company. and Jones''s attorney were all without actual knowledge of the existence of the right-of-way prior to the conveyance from Sloan to Jones.', 'If Jones sues Abstract Company for damages caused to Jones by the presence of the right-of-way, the most likely result will be a decision for', 'Jones, because Jones was a third-party creditor beneficiary of the contract between Sloan and Abstract Company', 'Jones, because the abstract prepared by Abstract Company constitutes a guarantee of Jones''s title to Newacre', 'Abstract Company, because Abstract Company had no knowledge of the existence of the right-of-way', 'Abstract Company, because there was no showing that any fraud was practiced upon Jones', 'A', 'A third-party beneficiary will only be bound by the terms of the underlying contract where the claims asserted by that beneficiary arise from its third-party beneficiary status.', 'mbe_347', 0, '42'),
('mbe_443', 'mbe', '443', '262', 'MBE-1978-83-part6', '', '43', 'The owner of Newacre executed and delivered to a power company a right-of-way deed for the building and maintenance of an overhead power line across Newacre. The deed was properly recorded. Newacre then passed through several intermediate conveyances until it was conveyed to Sloan about ten years after the date of the right-of-way deed. All the intermediate deeds were properly recorded, but none of them mentioned the right-of-way. Sloan entered into a written contract to sell Newacre to Jones. By the terms of the contract, Sloan promised to furnish an abstract of title to Jones. Sloan contracted directly with Abstract Company to prepare and deliver an abstract to Jones, and Abstract Company did so. The abstract omitted the right-of-way deed. Jones delivered the abstract to his attorney and asked the attorney for an opinion as to title. The attorney signed and delivered to Jones a letter stating that, from the attorney''s examination of the abstract, it was his "opinion that Sloan had a free and unencumbered marketable title to Newacre." Sloan conveyed Newacre to Jones by a deed which included covenants of general warranty and against encumbrances. Jones paid the full purchase price. After Jones had been in possession of Newacre for more than a year, he learned about the right-of-way deed. Sloan, Jones, Abstract Company. and Jones''s attorney were all without actual knowledge of the existence of the right-of-way prior to the conveyance from Sloan to Jones.', 'If Jones sues Sloan because of the presence of the right-of-way, the most likely result will be a decision for', 'Jones, because Sloan is liable for his negligent misrepresentation', 'Jones, because the covenants in Sloan''s deed to Jones have been breached', 'Sloan, because Jones relied upon Abstract Company, not Sloan, for information concerning title', 'Sloan, because Sloan was without knowledge of any defects in the title to Newacre', 'B', 'Negligent misrepresentation consists of: (1) a false statement of a material fact; (2) carelessness or negligence in ascertaining the truth of the statement by the party making it; (3) an intention to induce the other party to act; (4) action by the other party in reliance on the truth of the statement; and (5) damage to the other party resulting from such reliance when the party making the statement is under a duty to communicate accurate information. Fox Associates, Inc. v. Robert Half International, Inc., 334 Ill.App.3d 90, 94, 267 Ill.Dec. 800, 777 N.E.2d 603 (2002).', 'mbe_348', 0, '43'),
('mbe_444', 'mbe', '444', '263', 'MBE-1978-83-part6', '', '44', '', 'Congress enacts a criminal statute prohibiting "any person from interfering in any way with any right conferred on another person by the equal protection clause of the Fourteenth Amendment." Application of this statute to Jones, a private citizen, would be most clearly constitutional if Jones with threats of violence coerces', 'a public school teacher to exclude Black pupils from her class, solely because of their race', 'Black pupils, solely because of their race, to refrain from attending a privately owned and operated school licensed by the state', 'the bus driver operating a free school bus service under the sponsorship of a local church to refuse to allow Black pupils on the bus, solely because of their race', 'the federal official in charge of distributing certain federal benefits directly to students from distributing them to Black pupils. solely because of their race', 'A', 'The Supreme court has explained that fundamental rights, for equal protection purposes, are such rights as: a right of a uniquely private nature, the right to vote, right of interstate travel and rights guaranteed by the First Amendment. Massachusetts Bd. of Retirement v. Murgia, 96 S.Ct.at 2566.', 'mbe_349', 0, '44'),
('mbe_445', 'mbe', '445', '264', 'MBE-1978-83-part6', '', '45', 'Innes worked as a secretary in an office in a building occupied partly by her employer and partly by Glass, a retail store. The two areas were separated by walls and were in no way connected, except that the air conditioning unit served both areas and there was a common return-air duct. Glass began remodeling, and its employees did the work, which included affixing a plastic surfacing material to counters. To fasten the plastic to the counters, the employees purchased glue, with the brand name Stick, that was manufactured by Steel, packaged in a sealed container by Steel, and retailed by Paint Company. In the course of the remodeling job, one of Glass''s employees turned on the air conditioning and caused fumes from the glue to travel from Glass through the air conditioning unit and into Innes'' office. The employees did not know that there was common ductwork for the air conditioners. Innes was permanently blinded by the fumes from the glue. The label on the container of glue read, "DANGER. Do not smoke near this product. Extremely flammable. Contains Butanone, Toluol and Hexane. Use with adequate ventilation. Keep out of the reach of children." The three chemicals listed on the label are very toxic and harmful to human eyes. Steel had received no reports of eye injuries during the ten years that the Product had been manufactured and sold.', 'If Innes asserts a claim against Paint Company, the most likely result is that she will', 'recover if she can recover against Steel', 'recover, because Innes was an invitee of a tenant in the building', 'not recover unless Paint Company was negligent', 'not recover, because the glue came in a sealed package', 'A', 'An invitee is a person who enters the premises of another at the express or implied invitation of the owner or occupier for the parties'' mutual benefit. Chappell, 414 S.W.3d at 323; Forester, 329 S.W.3d at 837.', 'mbe_350', 0, '45'),
('mbe_446', 'mbe', '446', '264', 'MBE-1978-83-part6', '', '46', 'Innes worked as a secretary in an office in a building occupied partly by her employer and partly by Glass, a retail store. The two areas were separated by walls and were in no way connected, except that the air conditioning unit served both areas and there was a common return-air duct. Glass began remodeling, and its employees did the work, which included affixing a plastic surfacing material to counters. To fasten the plastic to the counters, the employees purchased glue, with the brand name Stick, that was manufactured by Steel, packaged in a sealed container by Steel, and retailed by Paint Company. In the course of the remodeling job, one of Glass''s employees turned on the air conditioning and caused fumes from the glue to travel from Glass through the air conditioning unit and into Innes'' office. The employees did not know that there was common ductwork for the air conditioners. Innes was permanently blinded by the fumes from the glue. The label on the container of glue read, "DANGER. Do not smoke near this product. Extremely flammable. Contains Butanone, Toluol and Hexane. Use with adequate ventilation. Keep out of the reach of children." The three chemicals listed on the label are very toxic and harmful to human eyes. Steel had received no reports of eye injuries during the ten years that the Product had been manufactured and sold.', 'If Innes asserts a claim against Glass, the most likely result is that she will', 'recover, because a user of a product is held to the same standard as the manufacturer', 'recover, because the employees of Glass caused the fumes to enter her area of the building', 'not recover, because Glass used the glue for its intended purposes', 'not recover, because the employees of Glass had no reason to know that the fumes could injure Innes', 'D', '“Under the doctrine of respondeat superior, an employer will be liable for the negligence of an employee committed while the employee is acting in the scope of his [or her] employment ... As a general rule, an employee driving to and from work is not acting in the scope of his [or her] employment ... Although such activity is work motivated, the element of control is lacking” (Lundberg v. State of New York, 25 N.Y.2d 467, 470–471, 306 N.Y.S.2d 947, 255 N.E.2d 177, rearg. denied 26 N.Y.2d 883, 309 N.Y.S.2d 1032, 258 N.E.2d 223; see Swierczynski v. O''Neill [Appeal No. 2], 41 A.D.3d 1145, 1146–1147, 840 N.Y.S.2d 855, lv. denied 9 N.Y.3d 812, 846 N.Y.S.2d 602, 877 N.E.2d 652; see also D''Amico v. Christie, 71 N.Y.2d 76, 88, 524 N.Y.S.2d 1, 518 N.E.2d 896).', 'mbe_351', 0, '46'),
('mbe_447', 'mbe', '447', '265', 'MBE-1978-83-part6', '', '47', 'When Esther, Gray''s 21-year-old daughter, finished college, Gray handed her a signed memorandum stating that if she would go to law school for three academic years, he would pay her tuition, room, and board and would "give her a $1,000 bonus" for each "A" she got in law school. Esther''s uncle, Miller, who was present on this occasion, read the memorandum and thereupon said to Esther, "and if he doesn''t pay your expenses, I will." Gray paid her tuition, room, and board for her first year but died just before the end of that year. Subsequently, Esther learned that she had received two "A''s" in the second semester. The executor of Gray''s estate has refused to pay her anything for the two "A''s" and has told her that the estate will no longer pay her tuition, room, and board in law school.', 'In an action by Esther against Miller on account of the executor''s repudiation of Gray''s promise to pay future tuition, room, and board, which of the following would be Miller''s strongest defense?', 'The parties did not manifestly intend a contract.', 'Gray''s death terminated the agreement.', 'The agreement was oral.', 'The agreement was divisible.', 'C', 'Gratuitous promises are not enforceable as contracts, because there is no consideration.', 'mbe_352', 0, '47'),
('mbe_448', 'mbe', '448', '265', 'MBE-1978-83-part6', '', '48', 'When Esther, Gray''s 21-year-old daughter, finished college, Gray handed her a signed memorandum stating that if she would go to law school for three academic years, he would pay her tuition, room, and board and would "give her a $1,000 bonus" for each "A" she got in law school. Esther''s uncle, Miller, who was present on this occasion, read the memorandum and thereupon said to Esther, "and if he doesn''t pay your expenses, I will." Gray paid her tuition, room, and board for her first year but died just before the end of that year. Subsequently, Esther learned that she had received two "A''s" in the second semester. The executor of Gray''s estate has refused to pay her anything for the two "A''s" and has told her that the estate will no longer pay her tuition, room, and board in law school.', 'In an action against Gray''s estate for $2,000 on account of the two "A''s," if the only defense raised is lack of consideration, Esther probably will', 'succeed under the doctrine of promissory estoppel', 'succeed on a theory of bargained-for exchange for her father''s promise', 'not succeed, because the $1,000 for each "A" was promised only as a bonus', 'not succeed, because Esther was already legally obligated to use her best efforts in law school', 'B', 'the “bargained-for-exchange” requirement does not prohibit the execution of form contracts presented on a take-it-or-leave it basis. See Metro East Center for Conditioning and Health v. Qwest Communications International, Inc., 294 F.3d 924, 926 (7th Cir.2002) (“Yet we have held that form contracts, offered on a take-it-or-leave-it basis, are agreements for purposes of the Arbitration Act.”). See, e.g., Koveleskie v. SBC Capital Markets, Inc., 167 F.3d 361, 367 (7th Cir.1999); Hill v. Gateway 2000, Inc., 105 F.3d 1147, 1148 (7th Cir.1997). Rather, under general contract principles a bargained-for exchange exists if one party''s promise induces the other party''s promise or performance. See Hartbarger v. SCA Services, Inc., 200 Ill.App.3d 1000, 146 Ill.Dec. 633, 558 N.E.2d 596, 604 (1990) (“A performance or return promise is bargained for if it is sought by the promisor in exchange for his promise and is given by the promisee in exchange for that promise.”) (quoting Restatement (Second) of Contracts § 71 (1981)). See also, Restatement (Second) of Contracts § 71, comment b at 173 (1981) (“ ‘Bargained for.’ In the typical bargain, the consideration and the promise bear a reciprocal relation of motive or inducement: the consideration induces the making of the promise and the promise induces the furnishing of the consideration.”).', 'mbe_353', 0, '48'),
('mbe_449', 'mbe', '449', '266', 'MBE-1978-83-part6', '', '49', '', 'In Polk''s negligence action against Dell arising out of a multiple-car collision, Witt testified for Polk that Dell went through a red light. On crossexamination, Dell seeks to question Witt about her statement that the light was yellow, made in a deposition that Witt gave in a separate action between Adams and Baker. The transcript of the deposition is self-authenticating. On proper objection, the court should rule the inquiry', 'admissible for impeachment only', 'admissible as substantive evidence only', 'admissible for impeachment and as substantive evidence', 'inadmissible, because it is hearsay not within any exception', 'C', 'A brief discussion of the nature of impeachment evidence would be helpful here. Unlike substantive evidence which is offered for the purpose of persuading the trier of fact as to the truth of a proposition on which the determination of the tribunal is to be asked, impeachment is that which is designed to discredit a witness, i. e., to reduce the effectiveness of his testimony by bringing forth evidence which explains why the jury should not put faith in him or his testimony. Examples of impeachment evidence would include prior inconsistent statements, bias, attacks on character of a witness, prior felony convictions, and attacks on the capacity of the witness to observe, recall or relate. See Udall, Arizona Law of Evidence, §§ 61–69, pp. 79–112.
Evidence may be both substantive and impeaching. In our earlier hypothetical of the surveillance movie, the movie may be substantive proof of the plaintiff''s injuries or lack thereof and it may be used to discredit her testimony. Another example would be evidence that a party was intoxicated. It is substantive evidence of negligence or contributory negligence and it also serves to discredit this party.', 'mbe_354', 0, '49'),
('mbe_450', 'mbe', '450', '267', 'MBE-1978-83-part6', '', '50', '', 'In 1965 Hubert Green executed his will which in pertinent part provided, "I hereby give, devise, and bequeath Greenvale to my surviving widow for life, remainder to such of my children as shall live to attain the age of 30 years, but if any child dies under the age of 30 years survived by a child or children, such child or children shall take and receive the share which his, her, or their parent would have received had such parent lived to attain the age of 30 years." At the date of writing his will, Green was married to Susan, and they had two children, Allan and Beth. Susan died in 1970 and Hubert married Waverly in 1972. At his death in 1980, Green was survived by his wife, Waverly, and three children, Allan, Beth, and Carter. Carter, who was born in 1974, was his child by Waverly. In a jurisdiction which recognizes the common-law Rule Against Perpetuities unmodified by statute, the result of the application of the rule is that the', 'remainder to the children and to the grandchildren is void because Green could have subsequently married a person who was unborn at the time Green executed his will', 'remainder to the children is valid, but the substitutionary gift to the grandchildren is void because Green could have subsequently married a person who was unborn at the time Green executed his will', 'gift in remainder to Allan and Beth or their children is valid, but the gift to Carter or his children is void', 'remainder to the children and the substitutionary gift to the grandchildren are valid', 'D', 'The rule against perpetuities in Virginia voids a contingent remainder or executory interest, created inter vivos or by will, which may, by some possibility, however unlikely that possibility may be, vest beyond a life or lives in being at the effective date of the instrument creating the interest, plus 21 years and 10 months. See Pleasants v. Pleasants, 6 Va. (2 Call) 319 (1798); Rose v. Rose, 191 Va. 171, 60 S.E.2d 45 (1950);  Burruss v. Baldwin, 199 Va. 883, 103 S.E.2d 249 (1958); White v. National Bank, 212 Va. 568, 186 S.E.2d 21 (1972).', 'mbe_355', 0, '50'),
('mbe_451', 'mbe', '451', '268', 'MBE-1978-83-part6', '', '51', '', 'Siddon worked as a private duty nurse and on occasion worked in Doctors'' Hospital. The hospital called Registry, the private duty referral agency through which Siddon usually obtained employment, and asked that in the future she not be assigned to patients in Doctors'' Hospital. Registry asked the hospital why it had made the request. Doctors'' Hospital sent a letter to Registry giving as the reason for its request that significant amounts of narcotics had disappeared during Siddon''s shifts from the nursing stations at which she had worked. If Siddon asserts a claim based on defamation against Doctors'' Hospital, Siddon will', 'recover, because the hospital accused Siddon of improper professional conduct', 'recover if Siddon did not take the narcotics', 'not recover if narcotics disappeared during Siddon''s shifts', 'not recover if the hospital reasonably believed that Siddon took the narcotics', 'D', 'a conditional privilege to utter a defamatory statement
“may be lost if the speaker does not believe that the statement is true or lacks reasonable grounds to believe that it is true; if it is published for a purpose other than that for which the particular privilege is given; if the publication is made to some person not reasonably believed to be necessary to accomplish the purpose; or if the publication includes defamatory matter not reasonably believed to be necessary to accomplish the purpose.” Lund v. Arbonne International, Inc., 132 Or.App. 87, 96, 887 P.2d 817 (1994).', 'mbe_356', 0, '51'),
('mbe_453', 'mbe', '453', '270', 'MBE-1985-part7', '', '1', '', 'Cycle Company manufactured a bicycle that it sold to Bike Shop, a retail bicycle dealer, which in turn sold it to Roth. Shortly thereafter, while Roth was riding the bicycle along a city street, he saw a traffic light facing him turn from green to amber. He sped up, hoping to cross the intersection before the light turned red. However, Roth quickly realized that he could not do so and applied the brake, which failed. To avoid the traffic that was then crossing in front of him, Roth turned sharply to his right and onto the sidewalk, where he struck P��rez, a pedestrian. Both P��rez and Roth sustained injuries. If P��rez asserts a claim based on negligence against Cycle Company and if it is found that the brake failure resulted from a manufacturing defect in the bicycle, will P��rez prevail?', 'Yes, because Cycle Company placed a defective bicycle into the stream of commerce.', 'Yes, if the defect could have been discovered through the exercise of reasonable care by Cycle Company.', 'No, because P��rez was not a purchaser of the bicycle.', 'No, if Roth was negligent in turning into the sidewalk.', 'B', 'The elements for a strict-liability manufacture defect claim are the same as those for a design defect claim: (i) the product is defective and unreasonably dangerous; (ii) the defective condition existed at the time the product left the defendant''s control; and (iii) the defective condition is the proximate cause of the plaintiff''s injuries. St. Clair, 2011 WL 5331674, at *4 (citing Dietz, 141 Ariz. at 110).', 'mbe_357', 0, '1'),
('mbe_454', 'mbe', '454', '271', 'MBE-1985-part7', '', '2', '', 'A federal statute sets up a program of dental education. The statute provides that the Secretary of Health and Human Services "shall, on a current basis, spend all of the money appropriated for this purpose" and "shall distribute the appropriated funds" by a specified formula to state health departments that agree I to participate in the program. In the current year I Congress has appropriated $100 million for expenditure on this program. In order to ensure a budget surplus in the current fiscal year, the President issues an executive order directing the various cabinet secretaries to cut expenditures in this year by 10 percent in all categories. He also orders certain programs to be cut more drastically because he believes that "they are not as important to the general welfare as other programs" The President identifies the dental education program as such a program and orders it to be cut by 50 percent. Assume that no other federal statutes are relevant. To satisfy constitutional requirements, how much money must the Secretary of Health and Human Services distribute for the dental education program this year?', '$50 million, because the President could reasonably determine that this program is not as important to the general welfare as other programs', '$50 million, because as chief executive the President has the constitutional authority to control the actions of all of his subordinates by executive order', '$90 million, because any more drastic cut for the program would be a denial of equal protection to beneficiaries of this program as compared to beneficiaries of other programs', '$100 million, because the President may not unilaterally suspend the effect of a valid federal statute imposing a duty to spend appropriated monies', 'D', 'And it is not claimed that express constitutional language grants this power to the President. The contention is that presidential power should be implied from the aggregate of his powers under the Constitution. Particular reliance is placed on provisions in Article II which say that “the executive Power shall be vested in a President * * *”; that “he shall take Care that the Laws be faithfully ** executed”; and that he “shall be Commander in Chief of the Army and Navy of the United States.” The order cannot properly be sustained as an exercise of the President''s military power as Commander in Chief of the Armed Forces.', 'mbe_358', 0, '2'),
('mbe_455', 'mbe', '455', '272', 'MBE-1985-part7', '', '3', '', 'Powers sued Debbs for battery. At trial, Powers'' witness Wilson testified that Debbs had made an unprovoked attack on Powers. On cross-examination, Debbs asks Wilson about a false claim that Wilson had once filed on an insurance policy. The question is', 'proper, because the conduct involved untruthfulness', 'proper provided that the conduct resulted in conviction of Wilson', 'improper, because the impeachment involved a specific instance of misconduct', 'improper, because the claim form would be the best evidence', 'A', 'In general a trial court has wide discretion in permitting leading questions and much depends upon circumstances and the subject matter of the questions. Hesse v. Wagner, 475 S.W.2d 55, 62[8] (Mo.1971). In a jury trial in a statutory rape prosecution where the prosecutrix is reluctant to testify or appears to be timid or in fear, the trial judge is permitted to exercise discretion in allowing leading questions to be propounded to her. State v. Palmer, 306 S.W.2d 441, 443[3] (Mo.1957); State v. Leigh, 580 S.W.2d 536, 541[5] (Mo.App.1979).', 'mbe_359', 0, '3'),
('mbe_456', 'mbe', '456', '273', 'MBE-1985-part7', '', '4', 'On May 1, Selco and Byco entered into a written agreement in which Selco agreed to fabricate and sell to Byco 10,000 specially designed brake linings for a new type of power brake manufactured by Byco. The contract provided that Byco would pay half of the purchase price on May 15 in order to give Selco funds to "tool up" for the work; that Selco would deliver 5,000 brake linings on May 31; that Byco would pay the balance of the purchase price on June 15; and that Selco would deliver the balance of the brake linings on June 30. On May 10, Selco notified Byco that it was doubtful whether Selco could perform because of problems encountered in modifying its production machines to produce the brake linings. On May 15, however, Selco assured Byco that the production difficulties had been overcome, and Byco paid Selco the first 50 percent installment of the purchase price. Selco did not deliver the first 5,000 brake linings on May 31, or at any time thereafter; and on June 10, Selco notified Byco that it would not perform the contract.', 'Which of the following correctly states Byco''s rights and obligations immediately after receipt of Selco''s notice on May 10?', 'Byco can treat the notice as an anticipatory repudiation, and has a cause of action on May 10 for breach of the entire contract.', 'Byco can treat the notice as an anticipatory repudiation, and can sue at once to enjoin an actual breach by Selco on May 31.', 'Byco has no cause of action for breach of contract, but can suspend its performance and demand assurances that Selco will perform.', 'Byco has no cause of action for breach of contract, and must pay the installment of the purchase price due on May 15 to preserve its rights under the contract.', 'C', 'A party''s uncured material breach of a contract can suspend or discharge the other party''s obligation to perform. See E. Allan Farnsworth, Contracts § 8.16, at 638–40 (2d ed.1990); see, e.g., Elec. Distribs., Inc. v. SFR, Inc., 166 F.3d 1074, 1086 (10th Cir.1999) (noting that a material breach excuses the other party''s performance under Colorado law). The Restatement (Second) of Contracts § 237 (1981) provides that “it is a condition of each party''s remaining duties to render performances ... that there be no uncured material failure by the other party to render any such performance due at an earlier time.” According to the Restatement, this doctrine is based on the principle that where performances are to be exchanged under an exchange of promises, each party is entitled to the assurance that he [or she] will not be called upon to perform his [or her] remaining duties of performance with respect to the expected exchange if there has already been an uncured material failure of performance by the other party.', 'mbe_360', 0, '4'),
('mbe_457', 'mbe', '457', '273', 'MBE-1985-part7', '', '5', 'On May 1, Selco and Byco entered into a written agreement in which Selco agreed to fabricate and sell to Byco 10,000 specially designed brake linings for a new type of power brake manufactured by Byco. The contract provided that Byco would pay half of the purchase price on May 15 in order to give Selco funds to "tool up" for the work; that Selco would deliver 5,000 brake linings on May 31; that Byco would pay the balance of the purchase price on June 15; and that Selco would deliver the balance of the brake linings on June 30. On May 10, Selco notified Byco that it was doubtful whether Selco could perform because of problems encountered in modifying its production machines to produce the brake linings. On May 15, however, Selco assured Byco that the production difficulties had been overcome, and Byco paid Selco the first 50 percent installment of the purchase price. Selco did not deliver the first 5,000 brake linings on May 31, or at any time thereafter; and on June 10, Selco notified Byco that it would not perform the contract.', 'Which of the following is NOT a correct statement of the parties'' legal status immediately after Selco''s notice on June 10?', 'Byco has a cause of action for total breach of contract because of Selco''s repudiation, but that cause of action will be lost if Selco retracts its repudiation before Byco changes its position or manifests to Selco that Byco considers the repudiation final.', 'Byco can bring suit to rescind the contract even if it elects to await Selco''s performance for a commercially reasonable time.', 'Byco can await performance by Selco for a commercially reasonable time, but if Byco awaits performance beyond that period, it cannot recover any resulting damages that it reasonably could have avoided.', 'Byco has a cause of action for breach of contract that it can successfully assert only after it has given Selco a commercially reasonable time to perform.', 'D', 'However, a material breach will not discharge an obligation of the non-breaching party that arose before the alleged breach. Where the parties promise to exchange performances, it is a condition of each party''s duty to render performance that there be no uncured material failure by the other party to render any such performance due at an earlier time. RESTATEMENT (SECOND) OF CONTRACTS § 237. Parties sometimes make several promises to exchange performances under a single contract. Under section 237, “only duties with respect to the performances to be exchanged under the particular exchange of promises are affected by a failure of one of those performances.... [A] duty under the same contract [is not] affected if it was not one to render a performance to be exchanged under an exchange of promises.... Furthermore, only duties to render performance are affected. A claim for damages that has already arisen as a result of a claim for partial breach is not discharged under the rule stated in this Section.” RESTATEMENT (SECOND) OF CONTRACTS § 237 cmt.', 'mbe_361', 0, '5'),
('mbe_458', 'mbe', '458', '274', 'MBE-1985-part7', '', '6', '', 'A state statute provides that persons moving into a community to attend a college on a full-time basis may not vote in any elections for local or state officials that are held in that community. Instead, the statute provides that for voting purposes all such persons shall retain their residence in the community from which they came. In that state the age of majority is eighteen. Which of the following is the strongest argument to demonstrate the unconstitutionality of this state statute?', 'A state does not have an interest that is sufficiently compelling to justify the exclusion from voting of an entire class of persons.', 'There are less restrictive means by which the state could assure that only actual residents of a community vote in its elections.', 'Most persons moving to a community to attend college full-time are likely to have attained the age of majority under the laws of this state.', 'On its face this statute impermissibly discriminates against interstate commerce.', 'B', 'Strict scrutiny requires the government to show that the regulation is narrowly tailored to serve a compelling government interest, with narrowly tailored meaning that “no ‘less restrictive alternative’ ” would serve its purpose. Cent. Radio Co. Inc. v. City of Norfolk, Va., 811 F.3d 625, 633 (4th Cir. 2016) (citation omitted); see Lukumi, 508 U.S. at 546, 113 S.Ct. 2217 (“To satisfy the commands of the First Amendment, a law restrictive of religious practice must advance ‘interests of the highest order’ and must be narrowly tailored in pursuit of those interests”). In applying strict scrutiny to a Florida law prohibiting judicial candidates from personally soliciting campaign donations, the Supreme Court found protecting the integrity of the judiciary to be a compelling interest, and that the law was narrowly tailored, because “[t]he solicitation ban aims squarely at the conduct most likely to undermine public confidence in the integrity of the judiciary” and “restricts a narrow slice of speech.” Williams-Yulee v. Fla. Bar, 575 U.S. 433, 449, 452, 135 S.Ct. 1656, 191 L.Ed.2d 570 (2015).', 'mbe_362', 0, '6'),
('mbe_459', 'mbe', '459', '275', 'MBE-1985-part7', '', '7', '', 'At a time when Ogawa held Lot 1 in the Fairoaks subdivision in fee simple, Vine executed a warranty deed that recited that Vine conveyed Lot 1, Fairoaks, to Purvis. The deed was promptly and duly recorded. After the recording of the deed from Vine to Purvis, Ogawa conveyed Lot I to Vine by a warranty deed that was promptly and duly recorded. Later, Vine conveyed the property to Rand by warranty deed and the deed was promptly and duly recorded. Rand paid the fair market value of Lot 1 and had no knowledge of any claim of Purvis. In an appropriate action, Rand and Purvis contest title to Lot 1. In this action, judgment should be for', 'Purvis, because Purvis'' deed is senior to Rand''s', 'Rand, because Rand paid value without notice of Purvis'' claim', 'Purvis or Rand, depending on whether a subsequent grantee is bound, at common law, by the doctrine of estoppel by deed', 'Purvis or Rand, depending on whether Purvis'' deed is deemed recorded in Rand''s chain of title', 'D', 'In real estate, the chain of title is the history of the property’s ownership. When a property is sold, the title is transferred, and these transfers form the chain. Researching the chain of title is among the tasks performed by a title company when a buyer signs a contract to purchase a property. The chain of title for any property is found in the relevant county recorder’s office, and there’s no reason you can’t conduct your own search to determine the chain of title. All the information is in the public record. Keep in mind that state laws governing the recording of real estate transfers differ, so the chain of title process in one state may differ somewhat from the chain of title process in another. 
Chain of Title Documents Formal documents maintain the chain of title. The chain ends with the most recent document affecting the property. Types of documents included are:
Transfer Documents
Financial Documents
Involuntary Liens
Covenants and Restrictions
Easements
Transfer documents (deeds) document the transfer of ownership. The deed conveys the property from the seller, or grantor, to the buyer, or grantee. The deed also includes a detailed description of the property.Financial documents (mortgages and deeds of trust) are voluntary liens, as the creditor enters into an agreement with a lender to borrow money to purchase the property. Until the debt is paid off, generally in 15 or 30 years, the lender has title to the property. Once the mortgage is paid, the former creditor owns the property “free and clear.” The date of the mortgage or lien determines which lien is a priority for payment if there is more than one lien in competition. A deed of trust, also known as a trust deed, assigns the property to a trustee. The trustee holds the title as security for a loan between the lender and the borrower. In such a case, the lender is known as the beneficiary and the borrower as the trustor.
Involuntary lien documents include liens, lis pendens and tax liens. Involuntary liens, as the name implies, are liens that arise without the owner’s consent, usually due to nonpayment of debts. Examples of involuntary liens include property tax liens when local property taxes are not paid; income tax liens, for failure to pay the IRS; judgment liens from a creditor, ordered by the court, and mechanic’s liens. The latter is filed by contractors if the owner does not pay for work done on the property. Involuntary liens “cloud” the title and require payment before the property changes hands. In some cases, the property is sold at auction to satisfy the lien. A lis pendens is notice that a lawsuit has been filed regarding the property’s title or ownership.
Covenants and restrictions are documents creating restrictions on the use of the subject property. Such restrictions may include limits on the types of improvements made to the property, uses of the property and property occupancy. Older homes may have covenants not permitting the sale of the property to people of certain racial or religious backgrounds, but these covenants are no longer enforceable.
Easements, also known as rights of way, are documents affecting usage rights. There are various types of easements, including:
Utility easements — allowing utility companies access to the property for the purpose of maintaining electrical lines, water/sewer lines and the like. These are the most common types of easements and affect most properties.
Private easements — a private easement allows another party, usually a neighbor, access through the property. It may mean direct access, such as a shared driveway, or non-direct access. An example of the latter is solar access, which means the owner cannot build or plant anything on the property that would affect a neighbor’s solar collection.
Easement by necessity — in some situations, the only way a neighboring landowner can access their property is by going through an adjacent property. This is known as easement by necessity, and the property owner cannot interfere with the neighbor’s ability to access his or her land.
Other documents involved in the chain of title may include:
Death certificates, when the property passes to a joint tenant through the right of survivorship. This joint tenant is generally the decedent’s spouse.
Affidavits, documents that affirm a fact related to the property
Correction deeds, used to correct an error in a previously recorded document
Chain of Title Breaks
Sometimes, there is a break in the chain of title. This occurs if the title transfer was inaccurate – or fraudulent. Human error is often to blame, especially if paperwork is filed in haste. That’s often the case during real estate booms, when lawyers and lenders were simply overwhelmed by the sheer amount of business. Common errors include misspellings of names of the grantor or grantee, incorrect legal descriptions of the property, lack of signatures on the deed, mistakes in when the chain of title documents were recorded, and even filing the deed in the wrong county. When there is a break in the chain of title, correction is necessary. The simplest ways to correct such breaks is to have the property owner go to court and seek quiet title action. Depending on the nature of the break, a judge can rule that the break is not relevant and no longer exists. However, if the break is known to have resulted due to a particular party, the owner can seek out the party and have them fill out a quitclaim deed, which gives up any rights to the property they may have had.
When it comes to chain of title and foreclosures, any break in the chain of title is a possible defense by an attorney for a foreclosed property owner.', 'mbe_363', 0, '7'),
('mbe_460', 'mbe', '460', '276', 'MBE-1985-part7', '', '8', '', 'Dillon held up a gasoline station. During the robbery he shot and killed a customer who attempted to apprehend him. Dillon was prosecuted for premeditated murder and convicted. Thereafter, he was indicted for armed robbery of the station. Before the trial, his attorney moved to dismiss the indictment on the ground that further proceedings were unconstitutional because of Dillon''s prior conviction. The motion to dismiss should be', 'granted, because once Dillon was convicted on any of the charges arising out of the robbery, the prosecution was constitutionally estopped from proceeding against Dillon on any charge stemming from the same transaction', 'granted, because the double jeopardy clause prohibits a subsequent trial on what is essentially a lesser included offense', 'denied, because there is no constitutional requirement that all known charges against Dillon be brought in the same prosecution', 'denied, because estoppel does not apply when the defendant is charged with violating two different statutes', 'C', 'double jeopardy bars a retrial when a conviction is reversed due to insufficient evidence presented at the first trial', 'mbe_364', 0, '8'),
('mbe_461', 'mbe', '461', '277', 'MBE-1985-part7', '', '9', '', 'Ellis, an electrical engineer, designed an electronic game known as Zappo. Ellis entered into a licensing agreement with Toyco under which Toyco agreed to manufacture Zappo according to Ellis'' specifications and to market it and pay a royalty to Ellis. Carla, whose parents had purchased a Zappo game for her, was injured while playing with the game. Carla recovered a judgment against Toyco on the basis of a finding that the Zappo game was defective because of Ellis'' improper design. In a claim for indemnity against Ellis, will Toyco prevail?', 'Yes, because as between Ellis and Toyco, Ellis was responsible for the design of Zappo.', 'Yes, because Toyco and Ellis were joint tortfeasors.', 'No, because Toyco, as the manufacturer, was strictly liable to Carla.', 'No, if Toyco, by a reasonable inspection, could have discovered the defect in the design of Zappo.', 'A', 'A product is defective when, at the time of sale or distribution, it contains a manufacturing defect, is defective in design, or is defective because of inadequate instructions or warnings. A product:
(a) contains a manufacturing defect when the product departs from its intended design even though all possible care was exercised in the preparation and marketing of the product;
(b) is defective in design when the foreseeable risks of harm posed by the product could have been reduced or avoided by the adoption of a reasonable alternative design by the seller or other distributor, or a predecessor in the commercial chain of distribution, and the omission of the alternative design renders the product not reasonably safe;
(c) is defective because of inadequate instructions or warnings when the foreseeable risks of harm posed by the product could have been reduced or avoided by the provision of reasonable instructions or warnings by the seller or other distributor, or a predecessor in the commercial chain of distribution, and the omission of the instructions or warnings renders the product not reasonably safe.', 'mbe_365', 0, '9'),
('mbe_462', 'mbe', '462', '278', 'MBE-1985-part7', '', '10', '', 'The Prindles have lived in their residential neighborhood for many years. Delbrook moved into the house next door and brought with him six hives of bees, from which he gathers honey for his own use. It is not possible for Delbrook to confine the bees to his property, and the bees settle on the Prindles'' flowers and bushes in such numbers that it is impossible for the Prindles to use their yard freely. The Prindles no longer enter their garden for fear of being stung by the bees. In a claim against Delbrook, will the Prindles prevail?', 'No, if beekeeping on Delbrook''s land was not prohibited by local ordinance.', 'No, unless the Prindles have been physically harmed by the bees.', 'Yes, because Delbrook''s bees intruded on the Prindles property.', 'Yes, because the Prindles cannot make normal use of their garden.', 'D', '“[A] plaintiff must prove four elements to succeed in a nuisance cause of action: (1) the condition complained of had a natural tendency to create danger and inflict injury [on] person or property; (2) the danger created was a continuing one; (3) the use of the land was unreasonable or unlawful; [and] (4) the existence of the nuisance was the proximate cause of the plaintiffs'' injuries and damages ... In addition, when the alleged tortfeasor is a municipality, our common law requires that the plaintiff also prove that the defendants, by some positive act, created the condition constituting the nuisance.” (Citation omitted; internal quotation marks omitted.) Picco v. Voluntown, 295 Conn. 141, 146, 989 A.2d 593 (2010).', 'mbe_366', 0, '10'),
('mbe_463', 'mbe', '463', '279', 'MBE-1985-part7', '', '11', '', 'While crossing Spruce Street, Pesko was hit by a car that she did not see. Pesko sued Dorry for her injuries. At trial, Pesko calls Williams, a police officer, to testify that, ten minutes after the accident, a driver stopped him and said, "Officer, a few minutes ago I saw a hit-and-run accident on Spruce Street involving a blue convertible, which I followed to the drive-in restaurant at Oak and Third," and that a few seconds later Williams saw Dorry sitting alone in a blue convertible in the drive-in restaurant''s parking lot. Williams'' testimony about the driver''s statement should be', 'admitted as a statement of recent perception', 'admitted as a present sense impression', 'excluded, because it is hearsay not within any exception', 'excluded, because it is more prejudicial than probative', 'C', 'To qualify as a present sense impression under Rule 803(1), a statement must “describ[e] or explain[ ] an event or condition” while the viewer is perceiving it or immediately thereafter. Payne argues that Reyes was perceiving Gonzales''s frustration with the children. But the statement at issue—Gonzales''s threat to kill the children—was not the sense impression. Nor did the statement qualify as an excited utterance under Rule 803(2). That rule requires that the statement “relate[ ] to a startling event or condition.”', 'mbe_367', 0, '11'),
('mbe_464', 'mbe', '464', '280', 'MBE-1985-part7', '', '12', '', 'Post sued Dean for personal injury alleged to have been caused by Dean''s negligence. A major issue at trial was whether Post''s disability was caused solely by trauma or by a preexisting condition of osteoarthritis. Post called Dr. Cox, who testified that the disability was caused by trauma. On cross-examination, Dr. Cox testified that a medical textbook entitled Diseases of the Joints was authoritative and that she agreed with the substance of passages from the textbook that she was directed to look at, but that the passages were inapplicable to Post''s condition because they dealt with rheumatoid arthritis rather than with the Osteoarthritis that Post was alleged to have. Dean then called his expert, Dr. Freed, who testified that, with reference to the issue being litigated, there is no difference between the two kinds of arthritis. Dean''s counsel than asks permission to read to the jury the textbook passages earlier shown to Dr. Cox. The judge should rule the textbook passages', 'admissible only for the purpose of impeaching Cox', 'admissible as substantive evidence if the judge determines that the passages are relevant.', 'inadmissible, because they are hearsay not within any exception.', 'inadmissible, because Cox contended that they are not relevant to Post''s condition', 'B', 'Substantial evidence is evidence that a reasonable mind might accept as adequate to support a conclusion; it may be less than a preponderance of the evidence, but must be more than a “mere scintilla.” Upky v. Marshall Mountain, LLC, 2008 MT 90, ¶ 22, 342 Mont. 273, ¶ 22, 180 P.3d 651, ¶ 22 (citation omitted).', 'mbe_368', 0, '12'),
('mbe_465', 'mbe', '465', '281', 'MBE-1985-part7', '', '13', 'The Kernel Corporation, through its president, Demeter Gritz, requested from Vault Finance, Inc., a short-term loan of $100,000. On April 1, Gritz and Vault''s loan officer agreed orally that Vault would make the loan on the following terms: (1) the loan would be repaid in full on or before the following July 1 and would carry interest at an annual rate of 15 percent (a lawful rate under the applicable usury law); and (2) Gritz would personally guarantee repayment. The loan was approved and made on April 5. The only document evidencing the loan was a memorandum, written and supplied by Vault and signed by Gritz for Kernel, that read in its entirety: April 5 In consideration of a loan advanced on this date, Kernel Corporation hereby promises to pay Vault Finance, Inc., $100,000 on September 1. Kernel Corporation By /s /Demeter Gritz Demeter Gritz, President Kernel Corporation did not repay the loan on or before July 1, although it had sufficient funds to do so. On July 10, Vault sued Kernel as principal debtor and Gritz individually as guarantor for $100,000, plus 15 percent interest from April 5.', 'At the trial, can Vault prove Kernel''s oral commitment to repay the loan on or before July 1?', 'Yes, because the oral agreement was supported by an independent consideration.', 'Yes, because evidence of the parties'' negotiations is relevant to their contractual intent concerning maturity of the debt.', 'No, because such evidence is barred by the preexisting duty rule.', 'No, because such evidence contradicts the writing and is barred by the parol evidence rule.', 'D', 'Generally, “[t]he parol evidence rule provides that extrinsic evidence is inadmissible to add to, vary, or explain the terms of a written instrument if the terms of the instrument are clear and unambiguous.” Cooper v. Cooper, 730 N.E.2d 212, 215 (Ind.Ct.App.2000) (citing Hauck v. Second Nat''l Bank of Richmond, 153 Ind.App. 245, 260, 286 N.E.2d 852, 861 (1972)).', 'mbe_369', 0, '13'),
('mbe_466', 'mbe', '466', '281', 'MBE-1985-part7', '', '14', 'The Kernel Corporation, through its president, Demeter Gritz, requested from Vault Finance, Inc., a short-term loan of $100,000. On April 1, Gritz and Vault''s loan officer agreed orally that Vault would make the loan on the following terms: (1) the loan would be repaid in full on or before the following July 1 and would carry interest at an annual rate of 15 percent (a lawful rate under the applicable usury law); and (2) Gritz would personally guarantee repayment. The loan was approved and made on April 5. The only document evidencing the loan was a memorandum, written and supplied by Vault and signed by Gritz for Kernel, that read in its entirety: April 5 In consideration of a loan advanced on this date, Kernel Corporation hereby promises to pay Vault Finance, Inc., $100,000 on September 1. Kernel Corporation By /s /Demeter Gritz Demeter Gritz, President Kernel Corporation did not repay the loan on or before July 1, although it had sufficient funds to do so. On July 10, Vault sued Kernel as principal debtor and Gritz individually as guarantor for $100,000, plus 15 percent interest from April 5.', 'At the trial, can Vault prove Gritz''s oral promise to guarantee the loan?', 'Yes, because Gritz signed the memorandum.', 'Yes, because, as president of the debtor-company, Gritz is a third-party beneficiary of the loan.', 'No, because there was no separate consideration for Gritz''s promise.', 'No, because such proof is barred by the statute of frauds.', 'D', 'Someone who wanted to enforce an oral promise otherwise made unenforceable by the statute of frauds would need only to incur modest costs in purported reliance on the promise—something easy, if risky, to do, as a premise for seeking to enforce an oral promise that may not have been made or may have been misunderstood.', 'mbe_370', 0, '14'),
('mbe_470', 'mbe', '470', '283', 'MBE-1985-part7', '', '18', '', 'O''Neal entered into a written contract to sell her house and six acres known as Meadowacre to Perez for $75,000. Delivery of the deed and payment of the purchase price were to be made six months after the contract. The contract provided that Meadowacre was to be conveyed "subject to easements, covenants, and restrictions of record"'' The contract was not recorded. After the contract was signed but before the deed was delivered, Electric Company decided to run a highvoltage power line in the area and required an easement through a portion of Meadowacre. O''Neal, by deed, granted an easement to Electric Company in consideration of $5,000; the deed was duly recorded. The power line would be a series of towers with several high-voltage lines that would be clearly visible from the house on Meadowacre but would in no way interfere with the house. When Perez caused the title to Meadowacre to be searched, the deed of easement to Electric Company was found. O''Neal appeared at the time and place scheduled for the closing and proffered an appropriate deed to Perez and demanded the purchase price. Perez refused to accept the deed. In an appropriate action for specific performance against Perez, O''Neal demanded $75,000. In this action, O''Neal should', 'obtain an order for specific performance at a price of $75,000', 'Obtain an order for specific performance at a price of $70,000', 'lose, because Perez did not contract to take subject to the easement to Electric Company', 'lose, because a high-voltage power line is a nuisance per se', 'C', 'When a property conveyance is “subject to” an existing deed of trust (in some states), the mortgage lien, through the deed of trust that secures it, stays on the home for the new owner to pay. The deed from the seller states that the buyer takes the property “subject to” the existing deed of trust.', 'mbe_371', 0, '18')
